interface Product {
  readonly id: number;
  name: string;
  price: number;
  discount?: number;
}

function describe(p: Product): string {
  const final = p.discount ? p.price - p.discount : p.price;
  return p.name + ' costs $' + final;
}

console.log(describe({ id: 1, name: 'Mug', price: 10 }));
console.log(describe({ id: 2, name: 'Shirt', price: 25, discount: 5 }));

