interface Repository {
  findById(id: number): string;
}

class UserRepo implements Repository {
  findById(id: number): string { return 'user ' + id; }
}

const repo: Repository = new UserRepo();
console.log(repo.findById(1));

interface Item {
  name: string;
  price: number;
}

interface Cart {
  items: Item[];
  addItem(item: Item): void;
  total(): number;
}

class ShoppingCart implements Cart {
  items: Item[] = [];
  addItem(item: Item): void {
    this.items.push(item);
  }
  total(): number {
    return this.items.reduce((sum, i) => sum + i.price, 0);
  }
}

const cart = new ShoppingCart();
cart.addItem({ name: 'Mug', price: 10 });
cart.addItem({ name: 'Shirt', price: 25 });
console.log(cart.items.length, cart.total());
